81	    return Math.log(Math.PI / Math.sin(Math.PI * z)) - logGamma(1 - z);
82	  }
83	  const w = z - 1;
84	  let x = LANCZOS[0];
85	  for (let i = 1; i < LANCZOS.length; i++) {
86	    x += LANCZOS[i] / (w + i);
87	  }
88	  const t = w + 7.5;
89	  return 0.5 * Math.log(2 * Math.PI) + (w + 0.5) * Math.log(t) - t + Math.log(x);
90	}
91	
92	// Lentz 连分式求值（Numerical Recipes betacf）
93	function betaContinuedFraction(a, b, x) {
94	  const MAX_ITER = 200;
95	  const EPS = 3e-14;
96	  const FPMIN = 1e-300;
97	  const qab = a + b;
98	  const qap = a + 1;
99	  const qam = a - 1;
100	  let c = 1;
101	  let d = 1 - (qab * x) / qap;
102	  if (Math.abs(d) < FPMIN) d = FPMIN;
103	  d = 1 / d;
104	  let h = d;
105	  for (let m = 1; m <= MAX_ITER; m++) {
106	    const m2 = 2 * m;
107	    let aa = (m * (b - m) * x) / ((qam + m2) * (a + m2));
108	    d = 1 + aa * d;
109	    if (Math.abs(d) < FPMIN) d = FPMIN;
110	    c = 1 + aa / c;
111	    if (Math.abs(c) < FPMIN) c = FPMIN;
112	    d = 1 / d;
113	    h *= d * c;
114	    aa = (-(a + m) * (qab + m) * x) / ((a + m2) * (qap + m2));
115	    d = 1 + aa * d;
116	    if (Math.abs(d) < FPMIN) d = FPMIN;
117	    c = 1 + aa / c;
118	    if (Math.abs(c) < FPMIN) c = FPMIN;
119	    d = 1 / d;
120	    const del = d * c;
121	    h *= del;
122	    if (Math.abs(del - 1) < EPS) break;
123	  }
124	  return h;
125	}
126	
127	// 正则化不完全 beta 函数 I_x(a, b)
128	function regularizedIncompleteBeta(x, a, b) {
129	  if (x <= 0) return 0;
130	  if (x >= 1) return 1;
131	  const lnFront =
132	    a * Math.log(x) + b * Math.log(1 - x) +
133	    logGamma(a + b) - logGamma(a) - logGamma(b);
134	  const front = Math.exp(lnFront);
135	  if (x < (a + 1) / (a + b + 2)) {
136	    return (front * betaContinuedFraction(a, b, x)) / a;
137	  }
138	  return 1 - (front * betaContinuedFraction(b, a, 1 - x)) / b;
139	}
140	
141	// 样本方差（无偏，除以 n-1）；调用方保证 values.length >= 2
142	function sampleVariance(values, avg) {
143	  let acc = 0;
144	  for (const v of values) {
145	    const d = v - avg;
146	    acc += d * d;
147	  }
148	  return acc / (values.length - 1);
149	}
150	
151	// 双侧 Welch t 检验：baseline 与 candidate 均为至少 2 个样本的数组。
152	// t 取候选减基线方向。返回保留六位小数的
153	// { t_statistic, degrees_of_freedom, p_value }。
154	// 两边方差均为 0 的退化情形：均值相同 -> {0, null, 1}；均值不同 -> {null, null, 0}。
155	function welchTest(baseline, candidate) {
156	  const n1 = baseline.length;
157	  const n2 = candidate.length;
158	  const m1 = meanOf(baseline);
159	  const m2 = meanOf(candidate);
160	  const v1 = sampleVariance(baseline, m1);
161	  const v2 = sampleVariance(candidate, m2);
162	
163	  if (v1 === 0 && v2 === 0) {
164	    if (m1 === m2) {
165	      return { t_statistic: 0, degrees_of_freedom: null, p_value: 1 };
166	    }
167	    return { t_statistic: null, degrees_of_freedom: null, p_value: 0 };
168	  }
169	
170	  const s1 = v1 / n1;
171	  const s2 = v2 / n2;
172	  const t = (m2 - m1) / Math.sqrt(s1 + s2);
173	  const df = (s1 + s2) ** 2 / (s1 ** 2 / (n1 - 1) + s2 ** 2 / (n2 - 1));
174	  const p = regularizedIncompleteBeta(df / (df + t * t), df / 2, 0.5);
175	  return {
176	    t_statistic: round6(t),
177	    degrees_of_freedom: round6(df),
178	    p_value: round6(p),
179	  };
180	}
181	
182	module.exports = { computeSummary, round6, welchTest };
